{
  "schemaVersion": "0.2",
  "slug": "trading-terminal",
  "name": "Trading terminal",
  "status": "experimental",
  "purpose": "Watch-only terminal fragment with a ticker, a symbol chart, and a working-order grid.",
  "scenarios": [
    "Scan a market ticker",
    "Select a symbol to update the price chart",
    "Inspect working orders for the selected symbol"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "onSelectSymbol": {
      "type": "event",
      "required": false,
      "description": "Called when a symbol action is activated."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Orders are present." },
    { "name": "empty", "description": "No orders to show." }
  ],
  "composition": {
    "allowedParents": ["page", "app-shell"],
    "allowedChildren": ["ticker", "data-grid", "chart", "button", "card", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not present this template as a live matching engine or order-entry path.",
    "Do not size the layout with viewport width media queries."
  ],
  "a11y": {
    "role": "region",
    "keyboard": ["Tab reaches ticker, symbol actions, chart, and grid"],
    "focus": "Symbol actions stay in document order with a visible focus ring.",
    "labeling": "Ticker, chart, grid, and symbol actions have accessible names.",
    "wcag": ["2.1.1", "2.4.7", "4.1.2"]
  },
  "responsive": {
    "strategy": "Chart and grid stack; @container at 48rem places them side by side. No viewport media queries.",
    "breakpoints": {
      "compact": "Chart and grid stack.",
      "medium": "Chart and grid sit in two columns at 48rem container inline-size.",
      "large": "Chart and grid remain in two columns."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "trading-terminal",
    "states": ["default", "empty"],
    "intents": ["watch-markets"]
  }
}

{
  "slug": "trading-terminal",
  "type": "registry:block",
  "name": "Trading terminal",
  "dependencies": ["button", "card", "chart", "data-grid", "ticker", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 1280,
    "title": "Ticker, symbol chart, and working orders"
  }
}

.cu-block-trading-terminal {
  container-type: inline-size;
  container-name: trading;
  display: grid;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-trading-terminal__header {
  display: grid;
  gap: var(--cu-space-2);
}

.cu-block-trading-terminal__meta {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-trading-terminal__symbols {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cu-space-2);
}

.cu-block-trading-terminal__body {
  display: grid;
  gap: var(--cu-space-3);
  grid-template-columns: minmax(0, 1fr);
}

@container trading (min-inline-size: 48rem) {
  .cu-block-trading-terminal__body {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

import { Button, Card, Chart, DataGrid, Ticker, Typography } from '@chameleon-ui/components'
import type { DataGridColumn, TickerItem } from '@chameleon-ui/components'
import { useMemo, useState } from 'react'
import { createBlockCopy } from '../copy.js'
import { tradingTerminalLocaleTrees } from './locale-map.js'
import './styles.css'

export interface TradingQuote extends TickerItem {
  series: number[]
}

export interface TradingOrder {
  id: string
  symbol: string
  side: 'buy' | 'sell'
  size: string
  price: string
}

export interface TradingTerminalProps {
  locale?: string
  quotes?: TradingQuote[]
  orders?: TradingOrder[]
  onSelectSymbol?: (id: string) => void
  className?: string
}

const DEFAULT_QUOTES: TradingQuote[] = [
  { id: 'btc', label: 'BTC', value: '67.2k', trend: 'up', series: [62, 64, 63, 66, 67] },
  { id: 'eth', label: 'ETH', value: '3.1k', trend: 'down', series: [3.4, 3.3, 3.2, 3.15, 3.1] },
  { id: 'sol', label: 'SOL', value: '148', trend: 'flat', series: [144, 147, 146, 148, 148] },
]

const DEFAULT_ORDERS: TradingOrder[] = [
  { id: 'ord-1', symbol: 'BTC', side: 'buy', size: '0.40', price: '67.1k' },
  { id: 'ord-2', symbol: 'ETH', side: 'sell', size: '2.00', price: '3.12k' },
  { id: 'ord-3', symbol: 'BTC', side: 'sell', size: '0.10', price: '67.4k' },
  { id: 'ord-4', symbol: 'SOL', side: 'buy', size: '12', price: '147' },
]

export function TradingTerminal({
  locale = 'en',
  quotes = DEFAULT_QUOTES,
  orders = DEFAULT_ORDERS,
  onSelectSymbol,
  className,
}: TradingTerminalProps) {
  const { t } = createBlockCopy(tradingTerminalLocaleTrees, locale)
  const [selectedId, setSelectedId] = useState(quotes[0]?.id ?? '')
  const classes = ['cu-block-trading-terminal', className].filter(Boolean).join(' ')
  const selected = quotes.find((quote) => quote.id === selectedId) ?? quotes[0]
  const visibleOrders = orders.filter((order) => !selected || order.symbol === selected.label)

  const columns: DataGridColumn<TradingOrder>[] = useMemo(
    () => [
      { key: 'symbol', header: t('trade.colSymbol'), width: 120 },
      {
        key: 'side',
        header: t('trade.colSide'),
        width: 120,
        render: (row) => (row.side === 'buy' ? t('trade.sideBuy') : t('trade.sideSell')),
      },
      { key: 'size', header: t('trade.colSize'), width: 120 },
      { key: 'price', header: t('trade.colPrice'), width: 120 },
    ],
    [t],
  )

  const handleSelect = (id: string) => {
    setSelectedId(id)
    onSelectSymbol?.(id)
  }

  return (
    <section
      className={classes}
      data-ai-role="trading-terminal"
      data-ai-intent="watch-markets"
      data-ai-state={orders.length === 0 ? 'empty' : 'default'}
    >
      <div className="cu-block-trading-terminal__header">
        <Typography variant="heading-1">{t('trade.title')}</Typography>
        <Typography variant="body">{t('trade.subtitle')}</Typography>
        <p className="cu-block-trading-terminal__meta">
          {t('trade.orderCount', { count: visibleOrders.length })}
        </p>
      </div>
      <Ticker items={quotes} label={t('trade.tickerLabel')} />
      <div className="cu-block-trading-terminal__symbols" role="group" aria-label={t('trade.tickerLabel')}>
        {quotes.map((quote) => (
          <Button
            aria-pressed={quote.id === selected?.id}
            key={quote.id}
            onClick={() => handleSelect(quote.id)}
            type="button"
            variant={quote.id === selected?.id ? 'solid' : 'outline'}
          >
            {t('trade.selectSymbol', { symbol: quote.label })}
          </Button>
        ))}
      </div>
      <div className="cu-block-trading-terminal__body">
        <Card padding="md" variant="outlined">
          {selected ? (
            <Chart
              emptyLabel={t('trade.emptyLabel')}
              label={t('trade.chartNamed', { symbol: selected.label })}
              series={[{ name: t('trade.priceSeries'), data: selected.series }]}
              type="line"
            />
          ) : null}
        </Card>
        <Card padding="md" variant="outlined">
          <DataGrid
            columns={columns}
            emptyLabel={t('trade.emptyLabel')}
            getRowId={(row) => row.id}
            height={240}
            label={t('trade.gridLabel')}
            rowHeight={40}
            rows={visibleOrders}
            width={640}
          />
        </Card>
      </div>
    </section>
  )
}
